package com.eventmanager.controller;
import com.eventmanager.dao.*; import com.eventmanager.model.User; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet("/dashboard") public class DashboardServlet extends HttpServlet { protected void doGet(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");if(u==null){res.sendRedirect("login.jsp");return;}try{if("ADMIN".equals(u.role)){req.setAttribute("users",new UserDAO().all());req.setAttribute("events",new EventDAO().all("PENDING"));req.getRequestDispatcher("admin.jsp").forward(req,res);}else if("ORGANIZER".equals(u.role)){req.setAttribute("events",new EventDAO().byOrganizer(u.id));req.getRequestDispatcher("organizer.jsp").forward(req,res);}else{req.setAttribute("events",new EventDAO().all("APPROVED"));req.getRequestDispatcher("attendee.jsp").forward(req,res);}}catch(Exception e){throw new ServletException(e);}} }
